void OpenMediaDevice(int32_t page_request_id, const char* device_id, blink::MediaStreamType type, OpenDeviceCallback callback, MediaDeviceSaltAndOrigin salt_and_origin) {
    if (!IsOriginAllowedToAccessDevice(salt_and_origin.origin)) {
        callback.Run(false, nullptr);
        return;
    }

    MediaStreamManager* manager = GetMediaStreamManager();
    if (manager) {
        manager->OpenDevice(page_request_id, device_id, type, callback, salt_and_origin, OnDeviceStopped);
    } else {
        callback.Run(false, nullptr);
    }
}

void OpenMediaDevice(int32_t page_request_id, const char* device_id, blink_MediaStreamType type, OpenDeviceCallback callback, MediaDeviceSaltAndOrigin salt_and_origin) {
